{
  "name": "happy-dog-runner",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "Happy Dog Runner — a branded, mobile-first 2D browser runner (Phaser 3 + TypeScript + Vite). Phase 1: foundation & scaffold.",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview",
    "typecheck": "tsc --noEmit",
    "gen:placeholders": "node scripts/gen-placeholders.mjs"
  },
  "dependencies": {
    "phaser": "^3.87.0"
  },
  "devDependencies": {
    "typescript": "^5.7.2",
    "vite": "^6.0.7"
  }
}

import { defineConfig } from 'vite';

// Static-site build (no backend). `base: './'` keeps every asset/script URL
// relative so the built `dist/` works when served from a domain root OR a
// sub-path (Cloudflare Pages / Netlify / a nested folder) without edits.
//
// Assets live in `public/assets/**` and are copied verbatim into `dist/assets/**`
// (Phaser loads them at runtime via `this.load.svg(key, 'assets/...')`), so we do
// NOT want Vite to inline or hash them — `publicDir` files are always emitted as-is.
export default defineConfig({
  base: './',
  build: {
    target: 'es2020',
    outDir: 'dist',
    assetsInlineLimit: 0,
    sourcemap: false,
  },
  server: {
    host: true,
    open: false,
  },
  preview: {
    host: true,
  },
});

/// <reference types="vite/client" />

// Typed contract for the VITE_* env vars this app reads (see src/config/env.ts).
// All optional: the app is correct when they are absent.
interface ImportMetaEnv {
  readonly VITE_GA4_ID?: string;
  readonly VITE_FB_PIXEL_ID?: string;
  readonly VITE_PROMO_CODE?: string;
  readonly VITE_BUY_URL?: string;
  readonly VITE_UTM_SOURCE?: string;
  readonly VITE_UTM_MEDIUM?: string;
  readonly VITE_UTM_CAMPAIGN?: string;
  readonly VITE_DEBUG_ANALYTICS?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}

/**
 * gameConfig.ts — the SINGLE SOURCE OF TRUTH for tuning constants.
 *
 * Every gameplay/tuning number lives here so playtest edits never touch scene
 * or entity logic (spec §8.2). Values are tagged:
 *   [SPEC]      — quoted exactly from the spec / brief; do not change casually.
 *   [SPEC-RANGE]— spec gives a range; the picked value sits inside it.
 *   [SUGGESTED] — spec leaves it open; this is a sensible default to tune.
 *
 * All pixel values are LOGICAL px at the fixed 1280×720 landscape resolution.
 */

// ── Logical resolution (landscape 16:9) — overrides the spec's portrait default ──
export const GAME_WIDTH = 1280; // [SPEC] canvas override: landscape 1280×720
export const GAME_HEIGHT = 720; // [SPEC] canvas override: landscape 1280×720

/** Canvas background (letterbox bars + default clear). */
export const BACKGROUND_COLOR = '#0f1418'; // [SUGGESTED]

// ── Health (spec §3.4) ──
export const MAX_HP = 3; // [SPEC] start with 3 hearts, hard cap
export const START_HP = 3; // [SPEC]
export const TICK_DAMAGE = 1; // [SPEC] tick collision = −1 HP
export const OBSTACLE_DAMAGE = 1; // [SPEC] bush/puddle = −1 HP (§11 Q10 assumption)
export const TABLET_HEAL = 1; // [SPEC] tablet = +1 HP, capped at MAX_HP
/** Post-hit invulnerability / blink window so one contact can't drain multiple HP. */
export const INVULN_MS = 1000; // [SPEC] ~1 s after damage (§3.4)

// ── Armor power-up (spec §3.7) ──
export const ARMOR_DURATION_MS = 5000; // [SPEC-RANGE] ~4–6 s total invulnerability
/** Approx. number of armor pickups that appear across one level. */
export const ARMOR_SPAWNS_PER_LEVEL = 2; // [SUGGESTED] "occasional, ~1–2/level" (§3.8)

// ── Level length & session duration (spec §3.9) ──
/**
 * Distance-based level. `LEVEL_LENGTH` is world units; HUD progress maps to
 * distance / LEVEL_LENGTH and the FinishLine spawns once at this position.
 * Tuned against the full speed ramp to land inside the 60–90 s window.
 */
export const LEVEL_LENGTH = 40000; // [SUGGESTED] ≈75 s at avg ~520 px/s
/** Target active-play duration window (seconds). */
export const TARGET_DURATION_S = { min: 60, max: 90, nominal: 75 } as const; // [SPEC] ~60–90 s

// ── Physics & jump (spec §3.2) ──
export const GRAVITY_Y = 2200; // [SUGGESTED] px/s²
export const JUMP_VELOCITY_Y = -900; // [SUGGESTED] px/s → peak ~184 px, air ~0.82 s
/** Hero is pinned at this screen X (left quarter); the world scrolls past it. */
export const HERO_X = 320; // [SUGGESTED]
/** Top of the ground band (ground occupies y 580 → 720); hero feet rest here. */
export const GROUND_TOP_Y = 580; // [SUGGESTED]

// ── Difficulty ramp (spec §3.8) ──
export const SCROLL_SPEED_START = 400; // [SUGGESTED] px/s at level start
export const SCROLL_SPEED_MAX = 700; // [SUGGESTED] px/s at level end
/** Hazard spacing eases from generous → tight over the run (always jump-clearable). */
export const HAZARD_SPACING_START = 640; // [SUGGESTED] px (within 520–700)
export const HAZARD_SPACING_END = 360; // [SUGGESTED] px (within 300–420)
/** Collectible generosity multiplier applied in the final quarter of the level. */
export const LATE_GENEROSITY_FACTOR = 0.65; // [SUGGESTED] taper to ~60–70% (§3.8)

// ── Scoring (spec §3.5) ──
export const TABLET_SCORE = 100; // [SUGGESTED] per-tablet (primary source)
export const SCORE_SURVIVAL_PER_S = 10; // [SUGGESTED] survival trickle per second

/** Persistence key for the mute preference (spec §6.3). */
export const MUTE_STORAGE_KEY = 'hdr:muted'; // [SUGGESTED]

/**
 * env.ts — runtime configuration read from VITE_* env vars.
 *
 * Every value has a safe placeholder default so the app is fully correct when
 * the vars are unset (dev, previews). Real IDs/codes are injected at build time
 * via `.env` (see `.env.example`). Never hardcode live IDs here.
 */

const env = import.meta.env;

/** Immutable, resolved runtime config. */
export const ENV = {
  /** GA4 Measurement ID (e.g. "G-XXXX"). Empty → GA4 disabled. */
  ga4Id: env.VITE_GA4_ID ?? '',
  /** Meta Pixel ID. Empty → Pixel disabled. */
  fbPixelId: env.VITE_FB_PIXEL_ID ?? '',
  /** Promo code surfaced on the CTA. Placeholder until client confirms (§11). */
  promoCode: env.VITE_PROMO_CODE ?? 'DOG10',
  /** Base buy URL; UTM params appended by buildBuyUrl(). */
  buyUrl: env.VITE_BUY_URL ?? 'https://tabletki.ua',
  /** Campaign attribution (UTM). */
  utmSource: env.VITE_UTM_SOURCE ?? 'happydogrunner',
  utmMedium: env.VITE_UTM_MEDIUM ?? 'game',
  utmCampaign: env.VITE_UTM_CAMPAIGN ?? 'tick_protection',
  /** Mirror analytics events to console for QA. */
  debugAnalytics: (env.VITE_DEBUG_ANALYTICS ?? 'false') === 'true',
} as const;

/**
 * Host portion of the buy URL, used as the fixed `destination` param of the
 * click_buy event (spec §7.2). Falls back to 'tabletki.ua' if the URL is odd.
 */
export function buyDestination(): string {
  try {
    return new URL(ENV.buyUrl).host || 'tabletki.ua';
  } catch {
    return 'tabletki.ua';
  }
}

/**
 * Build the UTM-tagged buy URL the CTA navigates to (spec §6.4). UTMs are
 * carried ALONGSIDE the promo code (which the player reads off the chip).
 */
export function buildBuyUrl(): string {
  try {
    const url = new URL(ENV.buyUrl);
    if (ENV.utmSource) url.searchParams.set('utm_source', ENV.utmSource);
    if (ENV.utmMedium) url.searchParams.set('utm_medium', ENV.utmMedium);
    if (ENV.utmCampaign) url.searchParams.set('utm_campaign', ENV.utmCampaign);
    return url.toString();
  } catch {
    // Misconfigured base URL — return it untouched rather than throwing.
    return ENV.buyUrl;
  }
}

/**
 * assetManifest.ts — the SINGLE SHARED asset contract for the whole game.
 *
 * PreloadScene iterates this manifest to load every asset via `load.svg`, and
 * `scripts/gen-placeholders.mjs` reads the same key/width/height set to emit the
 * Phase-1 greybox SVGs. Phase 2 REPLACES the SVG files against these EXACT keys
 * and dimensions — do not rename keys or change dims without updating both the
 * art and any code that positions the sprite.
 *
 * Conventions:
 *  - ALL graphics are SVG (locked override): one file per entity/state.
 *  - Keys are stable & namespaced (`dog_*`, `park_*`, `ui_*`, `vfx_*`, ...).
 *  - `path` is relative (no leading slash) so it resolves under any base path.
 *  - Dimensions are LOGICAL px at the 1280×720 landscape canvas; parallax /
 *    full-screen layers span the full 1280 width.
 */

export interface AssetDef {
  /** Stable texture key used everywhere in code. */
  readonly key: string;
  /** Always 'svg' in this project. */
  readonly type: 'svg';
  /** Rasterization width passed to load.svg (logical px). */
  readonly width: number;
  /** Rasterization height passed to load.svg (logical px). */
  readonly height: number;
  /** Path under /public, relative to the document base. */
  readonly path: string;
}

const asset = (key: string, width: number, height: number, folder: string): AssetDef => ({
  key,
  type: 'svg',
  width,
  height,
  path: `assets/${folder}/${key}.svg`,
});

export const ASSET_MANIFEST: readonly AssetDef[] = [
  // ── Hero dog — 5 states + armored variant (spec §4.1). One MVP dog. ──
  asset('dog_run', 140, 150, 'dog'), // default auto-run loop
  asset('dog_jump', 140, 150, 'dog'), // on tap (rise + fall)
  asset('dog_hit', 140, 150, 'dog'), // on −1 HP
  asset('dog_victory', 160, 170, 'dog'), // victory screen / crossing finish
  asset('dog_defeat', 160, 170, 'dog'), // game over
  asset('dog_armored', 150, 160, 'dog'), // armored run overlay/variant

  // ── Environment — park, parallax spans full 1280 width (spec §4.2) ──
  asset('park_bg_far', 1280, 720, 'env'), // far skyline/treeline (slowest)
  asset('park_bg_near', 1280, 360, 'env'), // near foliage (medium)
  asset('ground_tile', 256, 160, 'env'), // repeating ground/path tile (band y580→720)
  asset('park_fg_grass', 1280, 140, 'env'), // optional foreground grass tufts

  // ── Gameplay entities (spec §4.3) ──
  asset('tick', 64, 64, 'entities'), // damaging enemy
  asset('tablet', 56, 56, 'entities'), // collectible (the product)
  asset('bush', 150, 110, 'entities'), // jump obstacle
  asset('puddle', 180, 50, 'entities'), // jump obstacle
  asset('armor_pickup', 64, 64, 'entities'), // shield power-up pickup
  asset('finish_line', 96, 480, 'entities'), // spawned once at LEVEL_LENGTH

  // ── Armor VFX (spec §4.4) ──
  asset('vfx_armor_burst', 140, 140, 'vfx'), // pickup burst
  asset('vfx_armor_aura', 170, 170, 'vfx'), // persistent active aura (+ expiry flash)

  // ── UI kit (spec §4.5 / §6) ──
  asset('ui_heart_full', 52, 52, 'ui'), // HP heart (filled) — shape+fill, not colour alone
  asset('ui_heart_empty', 52, 52, 'ui'), // HP heart (empty)
  asset('ui_score_icon', 44, 44, 'ui'), // optional score icon
  asset('ui_btn_pause', 64, 64, 'ui'), // HUD pause button
  asset('ui_btn_mute_on', 64, 64, 'ui'), // mute toggle — sound ON state
  asset('ui_btn_mute_off', 64, 64, 'ui'), // mute toggle — sound OFF state
  asset('ui_progress_bar', 1180, 14, 'ui'), // full-width thin level-progress bar
  asset('ui_title_logo', 720, 260, 'ui'), // menu title / logo placeholder
  asset('ui_btn_play', 360, 104, 'ui'), // primary Play button
  asset('ui_promo_chip', 460, 120, 'ui'), // promo-code chip on results
  asset('ui_btn_cta', 380, 100, 'ui'), // buy CTA button
  asset('ui_btn_play_again', 300, 84, 'ui'), // secondary "play again" button
  asset('ui_pause_panel', 520, 360, 'ui'), // centered pause overlay panel

  // ── Full-screen backgrounds (spec §4.5 / §6) ──
  asset('screen_bg_menu', 1280, 720, 'screens'), // main menu backdrop
  asset('screen_bg_victory', 1280, 720, 'screens'), // victory results backdrop
  asset('screen_bg_gameover', 1280, 720, 'screens'), // game-over results backdrop
] as const;

/**
 * Typo-safe key accessors. Prefer `KEYS.dog_run` over the bare string in code so
 * a renamed asset surfaces as a compile error, not a silent missing texture.
 */
export const KEYS = Object.fromEntries(
  ASSET_MANIFEST.map((a) => [a.key, a.key]),
) as { readonly [K in (typeof ASSET_MANIFEST)[number]['key']]: K };

/**
 * assetManifest.ts — the SINGLE SHARED asset contract for the whole game.
 *
 * PreloadScene iterates this manifest to load every asset via `load.svg`, and
 * `scripts/gen-placeholders.mjs` reads the same key/width/height set to emit the
 * Phase-1 greybox SVGs. Phase 2 REPLACES the SVG files against these EXACT keys
 * and dimensions — do not rename keys or change dims without updating both the
 * art and any code that positions the sprite.
 *
 * Conventions:
 *  - ALL graphics are SVG (locked override): one file per entity/state.
 *  - Keys are stable & namespaced (`dog_*`, `park_*`, `ui_*`, `vfx_*`, ...).
 *  - `path` is relative (no leading slash) so it resolves under any base path.
 *  - Dimensions are LOGICAL px at the 1280×720 landscape canvas; parallax /
 *    full-screen layers span the full 1280 width.
 */

export interface AssetDef {
  /** Stable texture key used everywhere in code. */
  readonly key: string;
  /** Always 'svg' in this project. */
  readonly type: 'svg';
  /** Rasterization width passed to load.svg (logical px). */
  readonly width: number;
  /** Rasterization height passed to load.svg (logical px). */
  readonly height: number;
  /** Path under /public, relative to the document base. */
  readonly path: string;
}

// Generic over the key so literal key types survive inference (powers `AssetKey`
// and the typo-safe `KEYS` lookup below).
const asset = <K extends string>(key: K, width: number, height: number, folder: string) => ({
  key,
  type: 'svg' as const,
  width,
  height,
  path: `assets/${folder}/${key}.svg`,
});

export const ASSET_MANIFEST = [
  // ── Hero dog — 5 states + armored variant (spec §4.1). One MVP dog. ──
  asset('dog_run', 140, 150, 'dog'), // default auto-run loop
  asset('dog_jump', 140, 150, 'dog'), // on tap (rise + fall)
  asset('dog_hit', 140, 150, 'dog'), // on −1 HP
  asset('dog_victory', 160, 170, 'dog'), // victory screen / crossing finish
  asset('dog_defeat', 160, 170, 'dog'), // game over
  asset('dog_armored', 150, 160, 'dog'), // armored run overlay/variant

  // ── Environment — park, parallax spans full 1280 width (spec §4.2) ──
  asset('park_bg_far', 1280, 720, 'env'), // far skyline/treeline (slowest)
  asset('park_bg_near', 1280, 360, 'env'), // near foliage (medium)
  asset('ground_tile', 256, 160, 'env'), // repeating ground/path tile (band y580→720)
  asset('park_fg_grass', 1280, 140, 'env'), // optional foreground grass tufts

  // ── Gameplay entities (spec §4.3) ──
  asset('tick', 64, 64, 'entities'), // damaging enemy
  asset('tablet', 56, 56, 'entities'), // collectible (the product)
  asset('bush', 150, 110, 'entities'), // jump obstacle
  asset('puddle', 180, 50, 'entities'), // jump obstacle
  asset('armor_pickup', 64, 64, 'entities'), // shield power-up pickup
  asset('finish_line', 96, 480, 'entities'), // spawned once at LEVEL_LENGTH

  // ── Armor VFX (spec §4.4) ──
  asset('vfx_armor_burst', 140, 140, 'vfx'), // pickup burst
  asset('vfx_armor_aura', 170, 170, 'vfx'), // persistent active aura (+ expiry flash)

  // ── UI kit (spec §4.5 / §6) ──
  asset('ui_heart_full', 52, 52, 'ui'), // HP heart (filled) — shape+fill, not colour alone
  asset('ui_heart_empty', 52, 52, 'ui'), // HP heart (empty)
  asset('ui_score_icon', 44, 44, 'ui'), // optional score icon
  asset('ui_btn_pause', 64, 64, 'ui'), // HUD pause button
  asset('ui_btn_mute_on', 64, 64, 'ui'), // mute toggle — sound ON state
  asset('ui_btn_mute_off', 64, 64, 'ui'), // mute toggle — sound OFF state
  asset('ui_progress_bar', 1180, 14, 'ui'), // full-width thin level-progress bar
  asset('ui_title_logo', 720, 260, 'ui'), // menu title / logo placeholder
  asset('ui_btn_play', 360, 104, 'ui'), // primary Play button
  asset('ui_promo_chip', 460, 120, 'ui'), // promo-code chip on results
  asset('ui_btn_cta', 380, 100, 'ui'), // buy CTA button
  asset('ui_btn_play_again', 300, 84, 'ui'), // secondary "play again" button
  asset('ui_pause_panel', 520, 360, 'ui'), // centered pause overlay panel

  // ── Full-screen backgrounds (spec §4.5 / §6) ──
  asset('screen_bg_menu', 1280, 720, 'screens'), // main menu backdrop
  asset('screen_bg_victory', 1280, 720, 'screens'), // victory results backdrop
  asset('screen_bg_gameover', 1280, 720, 'screens'), // game-over results backdrop
];

/** Union of every valid asset key (literal), derived from the manifest. */
export type AssetKey = (typeof ASSET_MANIFEST)[number]['key'];

/**
 * Typo-safe key accessors. Prefer `KEYS.dog_run` over the bare string in code so
 * a renamed asset surfaces as a compile error, not a silent missing texture.
 */
export const KEYS = Object.fromEntries(ASSET_MANIFEST.map((a) => [a.key, a.key])) as {
  readonly [K in AssetKey]: K;
};

/**
 * strings.ts — tiny i18n layer. Ukrainian is the primary locale (spec §11 Q4);
 * adding a locale is just another entry in STRINGS. `t(key)` looks up the
 * current locale, falls back to Ukrainian, and supports `{var}` interpolation.
 */

export type Locale = 'uk' | 'en';

const DEFAULT_LOCALE: Locale = 'uk';
let currentLocale: Locale = DEFAULT_LOCALE;

/**
 * Ukrainian dictionary — the authoritative key set. Every UI string used by any
 * scene (incl. the rotate-device hint) lives here.
 */
const uk = {
  // Loading
  loading: 'Завантаження…',

  // Menu
  menu_title: 'Щасливий Пес',
  menu_subtitle: 'Забіг парком',
  menu_play: 'Грати',
  menu_hint: 'Тапни, щоб стрибнути — уникай кліщів!',
  menu_sound_on: 'Звук: увімкнено',
  menu_sound_off: 'Звук: вимкнено',

  // HUD
  hud_score: 'Рахунок',

  // Game (Phase-1 temporary debug controls)
  game_debug_hint: 'ДЕМО: завершити забіг →',
  game_debug_win: '🏁 Перемога (демо)',
  game_debug_lose: '☠ Поразка (демо)',

  // Results
  results_victory_title: 'Ти впорався! 🐕',
  results_gameover_title: 'Кліщі тебе наздогнали…',
  results_score: 'Рахунок: {score}',
  results_promo_label: 'Промокод:',
  results_cta: 'Купити на tabletki.ua',
  results_play_again: 'Грати ще раз',

  // Orientation guard
  rotate_title: 'Поверни пристрій',
  rotate_body: 'Гра працює горизонтально 📱↻',
} as const;

/** Every valid string key (derived from the Ukrainian dictionary). */
export type StringKey = keyof typeof uk;

/** Optional partial overrides for other locales; missing keys fall back to `uk`. */
const en: Partial<Record<StringKey, string>> = {
  loading: 'Loading…',
  menu_title: 'Happy Dog',
  menu_subtitle: 'Park Run',
  menu_play: 'Play',
  menu_hint: 'Tap to jump — dodge the ticks!',
  menu_sound_on: 'Sound: on',
  menu_sound_off: 'Sound: off',
  hud_score: 'Score',
  game_debug_hint: 'DEMO: finish run →',
  game_debug_win: '🏁 Victory (demo)',
  game_debug_lose: '☠ Defeat (demo)',
  results_victory_title: 'You made it! 🐕',
  results_gameover_title: 'The ticks got you…',
  results_score: 'Score: {score}',
  results_promo_label: 'Promo code:',
  results_cta: 'Buy on tabletki.ua',
  results_play_again: 'Play again',
  rotate_title: 'Rotate your device',
  rotate_body: 'This game plays in landscape 📱↻',
};

const STRINGS: Record<Locale, Partial<Record<StringKey, string>>> = { uk, en };

export function setLocale(locale: Locale): void {
  currentLocale = locale;
}

export function getLocale(): Locale {
  return currentLocale;
}

/**
 * Translate `key` for the current locale. Falls back to Ukrainian for any key
 * missing in the active locale. `vars` fills `{name}` placeholders.
 */
export function t(key: StringKey, vars?: Record<string, string | number>): string {
  // `uk[key]` is always a string (concrete dictionary), so the result is too.
  let out: string = STRINGS[currentLocale][key] ?? uk[key];
  if (vars) {
    for (const [name, value] of Object.entries(vars)) {
      out = out.split(`{${name}}`).join(String(value));
    }
  }
  return out;
}

/**
 * track.ts — the SINGLE analytics choke point (spec §7.1).
 *
 * Game code never touches gtag/fbq directly; it calls the typed `track()`
 * overloads, which fan out to GA4 (gtag) and Meta Pixel (fbq). Everything here
 * is safe when the pixels are absent/blocked (optional chaining) and gated on a
 * consent hook. Real GA4/Pixel loading is finished in Phase 5 — `initAnalytics`
 * already env-gates the loader so no live IDs are hardcoded.
 */

import { ENV } from '../config/env';

declare global {
  interface Window {
    gtag?: (...args: unknown[]) => void;
    fbq?: ((...args: unknown[]) => void) & { callMethod?: (...args: unknown[]) => void };
    dataLayer?: unknown[];
    _fbq?: unknown;
  }
}

/** The three funnel events — names are FIXED by the brief (§3B); do not rename. */
export type AnalyticsEvent = 'start_game' | 'finish_game' | 'click_buy';

/** `start_game` — a round begins. No params required (spec §7.2). */
export type StartGameParams = Record<string, never>;

/** `finish_game` — a round ends (win OR lose) (spec §7.2). */
export interface FinishGameParams {
  result: 'win' | 'lose';
  score: number;
  /** Active play time in seconds, EXCLUDING paused time. */
  duration_s: number;
}

/** `click_buy` — the results-screen CTA was tapped (spec §7.2). */
export interface ClickBuyParams {
  destination: string;
  promo_code: string;
}

// ── Consent gate (spec §7.4) ───────────────────────────────────────────────
// The adapter ships "consent-ready": a single flag every event passes through.
// A future CMP flips it via setAnalyticsConsent(); until then it defaults to
// granted so the funnel is observable in dev/QA.
let consentGranted = true;

export function setAnalyticsConsent(granted: boolean): void {
  consentGranted = granted;
}

function hasConsent(): boolean {
  return consentGranted;
}

// ── track() — typed overloads so call sites get the right param shape ──────
export function track(event: 'start_game', params?: StartGameParams): void;
export function track(event: 'finish_game', params: FinishGameParams): void;
export function track(event: 'click_buy', params: ClickBuyParams): void;
export function track(event: AnalyticsEvent, params: Record<string, unknown> = {}): void {
  if (!hasConsent()) return;

  // GA4
  window.gtag?.('event', event, params);
  // Meta Pixel — custom events via trackCustom
  window.fbq?.('trackCustom', event, params);

  if (ENV.debugAnalytics) {
    // Intentional QA mirror, gated behind VITE_DEBUG_ANALYTICS.
    console.debug('[track]', event, params);
  }
}

// ── initAnalytics() — env-gated loader (called once from main.ts) ──────────
// Injects the GA4 / Pixel bootstraps ONLY when their IDs are present and consent
// is granted. With no IDs (dev/preview) this is a no-op and track() stays safe.
let initialized = false;

export function initAnalytics(): void {
  if (initialized || !hasConsent()) return;
  initialized = true;

  if (ENV.ga4Id) loadGa4(ENV.ga4Id);
  if (ENV.fbPixelId) loadPixel(ENV.fbPixelId);
}

function loadGa4(measurementId: string): void {
  const s = document.createElement('script');
  s.async = true;
  s.src = `https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(measurementId)}`;
  document.head.appendChild(s);

  window.dataLayer = window.dataLayer ?? [];
  const gtag: (...args: unknown[]) => void = (...args) => {
    window.dataLayer?.push(args);
  };
  window.gtag = gtag;
  gtag('js', new Date());
  gtag('config', measurementId);
}

function loadPixel(pixelId: string): void {
  if (!window.fbq) {
    const fbq = ((...args: unknown[]) => {
      fbq.callMethod ? fbq.callMethod(...args) : fbq.queue.push(args);
    }) as ((...args: unknown[]) => void) & {
      callMethod?: (...args: unknown[]) => void;
      queue: unknown[][];
      loaded: boolean;
      version: string;
    };
    fbq.queue = [];
    fbq.loaded = true;
    fbq.version = '2.0';
    window.fbq = fbq;
    window._fbq = window._fbq ?? fbq;

    const s = document.createElement('script');
    s.async = true;
    s.src = 'https://connect.facebook.net/en_US/fbevents.js';
    document.head.appendChild(s);
  }
  window.fbq('init', pixelId);
  window.fbq('track', 'PageView');
}

import Phaser from 'phaser';
import { MUTE_STORAGE_KEY } from '../config/gameConfig';

/**
 * AudioManager — mute state + persistence (spec §6.3) and the iOS audio-unlock
 * hook (spec §10.2). No audio assets are loaded in Phase 1; this manages the
 * game's sound manager (`scene.sound`) so mute is honoured the moment SFX/music
 * land in a later phase. Mute is a single persisted flag shared across scenes.
 */

function readStoredMute(): boolean {
  try {
    return localStorage.getItem(MUTE_STORAGE_KEY) === '1';
  } catch {
    return false; // private mode / storage disabled
  }
}

function persistMute(value: boolean): void {
  try {
    localStorage.setItem(MUTE_STORAGE_KEY, value ? '1' : '0');
  } catch {
    /* ignore — non-persistent session is acceptable */
  }
}

let muted = readStoredMute();

export const AudioManager = {
  isMuted(): boolean {
    return muted;
  },

  /** Push the persisted mute state onto a game's sound manager. */
  apply(sound: Phaser.Sound.BaseSoundManager): void {
    sound.mute = muted;
  },

  /** Toggle mute, persist, and apply. Returns the new muted state. */
  toggle(sound: Phaser.Sound.BaseSoundManager): boolean {
    muted = !muted;
    sound.mute = muted;
    persistMute(muted);
    return muted;
  },

  /**
   * iOS Safari audio-unlock STUB. Web audio is suspended until a user gesture,
   * so resume the context on the first pointer input.
   * TODO(phase-5): verify on real iOS Safari once audio assets exist, and
   * confirm a muted player who taps Play stays muted through the unlock.
   */
  unlockOnFirstPointer(scene: Phaser.Scene): void {
    scene.input.once(Phaser.Input.Events.POINTER_DOWN, () => {
      const sound = scene.sound;
      if (
        sound instanceof Phaser.Sound.WebAudioSoundManager &&
        sound.context.state === 'suspended'
      ) {
        void sound.context.resume();
      }
    });
  },
};

import { t } from '../i18n/strings';

/**
 * Orientation guard STUB (Phase 1). A DOM overlay above the canvas that shows a
 * centered "rotate to landscape" hint while the viewport is portrait and hides
 * in landscape. Minimal inline styling — Phase 2 may brand/restyle it. It lives
 * in the DOM (not a Phaser scene) so it works across every scene at once.
 */
export function installOrientationGuard(): void {
  if (document.getElementById('orientation-guard')) return;

  const overlay = document.createElement('div');
  overlay.id = 'orientation-guard';
  overlay.setAttribute('role', 'alertdialog');
  overlay.setAttribute('aria-live', 'polite');

  const inner = document.createElement('div');
  const title = document.createElement('div');
  title.textContent = t('rotate_title');
  const body = document.createElement('div');
  body.textContent = t('rotate_body');
  inner.append(title, body);
  overlay.append(inner);

  Object.assign(overlay.style, {
    position: 'fixed',
    top: '0',
    left: '0',
    width: '100%',
    height: '100%',
    display: 'none',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'rgba(15, 20, 24, 0.92)',
    color: '#f4f7fa',
    zIndex: '9999',
    textAlign: 'center',
    fontFamily: 'system-ui, sans-serif',
    padding: '24px',
    boxSizing: 'border-box',
  });
  Object.assign(title.style, { fontSize: '24px', fontWeight: '700', marginBottom: '10px' });
  Object.assign(body.style, { fontSize: '16px', opacity: '0.85' });

  document.body.append(overlay);

  const portrait = window.matchMedia('(orientation: portrait)');
  const update = (): void => {
    overlay.style.display = portrait.matches ? 'flex' : 'none';
  };

  if (typeof portrait.addEventListener === 'function') {
    portrait.addEventListener('change', update);
  }
  window.addEventListener('resize', update);
  window.addEventListener('orientationchange', update);
  update();
}

import Phaser from 'phaser';

/**
 * createButton — a small reusable button factory used across scenes (Play, CTA,
 * Play-again, the Phase-1 debug finish buttons). Backed by an SVG texture when
 * one is given, otherwise a drawn rectangle (handy for temporary/debug buttons).
 * Returns an interactive Container with hover/press feedback.
 */
export interface ButtonOptions {
  x: number;
  y: number;
  onClick: () => void;
  /** Background texture key. If omitted, a rectangle is drawn instead. */
  texture?: string;
  /** Centered label text. */
  label?: string;
  /** Explicit hit size; defaults to the texture size, or 220×64 for the rect. */
  width?: number;
  height?: number;
  /** Overrides merged onto the default label text style. */
  labelStyle?: Phaser.Types.GameObjects.Text.TextStyle;
}

const DEFAULT_LABEL_STYLE: Phaser.Types.GameObjects.Text.TextStyle = {
  fontFamily: 'system-ui, sans-serif',
  fontSize: '26px',
  fontStyle: '700',
  color: '#f4f7fa',
};

export function createButton(scene: Phaser.Scene, opts: ButtonOptions): Phaser.GameObjects.Container {
  const container = scene.add.container(opts.x, opts.y);

  let width = opts.width ?? 0;
  let height = opts.height ?? 0;

  if (opts.texture) {
    const bg = scene.add.image(0, 0, opts.texture).setOrigin(0.5);
    width = width || bg.width;
    height = height || bg.height;
    container.add(bg);
  } else {
    width = width || 220;
    height = height || 64;
    const rect = scene.add
      .rectangle(0, 0, width, height, 0x2b3a46)
      .setStrokeStyle(2, 0x5b6670)
      .setOrigin(0.5);
    container.add(rect);
  }

  if (opts.label !== undefined) {
    const style: Phaser.Types.GameObjects.Text.TextStyle = { ...DEFAULT_LABEL_STYLE, ...opts.labelStyle };
    const text = scene.add.text(0, 0, opts.label, style).setOrigin(0.5);
    container.add(text);
  }

  container.setSize(width, height);
  container.setInteractive(
    new Phaser.Geom.Rectangle(-width / 2, -height / 2, width, height),
    Phaser.Geom.Rectangle.Contains,
  );
  if (container.input) {
    container.input.cursor = 'pointer';
  }

  container.on(Phaser.Input.Events.POINTER_OVER, () => container.setScale(1.04));
  container.on(Phaser.Input.Events.POINTER_OUT, () => container.setScale(1));
  container.on(Phaser.Input.Events.POINTER_DOWN, () => container.setScale(0.96));
  container.on(Phaser.Input.Events.POINTER_UP, () => {
    container.setScale(1.04);
    opts.onClick();
  });

  return container;
}

import Phaser from 'phaser';
import { KEYS } from '../config/assetManifest';

/**
 * HeroDog — the player avatar.
 *
 * Phase 1 is a PLACEHOLDER: it renders the run sprite pinned at a fixed screen X
 * (the world will scroll past it later) with a gentle idle bob, plus a cosmetic
 * squash-hop on tap to prove the input path end-to-end. No physics/HP yet.
 *
 * Phase 2 turns this into a `Phaser.Physics.Arcade.Sprite` with HP and the five
 * animation states (run/jump/hit/victory/defeat) — the class boundary is here so
 * that is an additive change, not a rewrite.
 */
export class HeroDog extends Phaser.GameObjects.Sprite {
  constructor(scene: Phaser.Scene, x: number, y: number) {
    super(scene, x, y, KEYS.dog_run);
    this.setOrigin(0.5, 1); // feet rest on the ground line at `y`
    scene.add.existing(this);

    // Idle bob so the placeholder reads as "alive".
    scene.tweens.add({
      targets: this,
      y: y - 6,
      duration: 420,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.inOut',
    });
  }

  /** Cosmetic squash-hop on tap (Phase 1 has no real jump physics yet). */
  nudgeJump(): void {
    this.scene.tweens.add({
      targets: this,
      scaleX: 1.08,
      scaleY: 0.9,
      duration: 90,
      yoyo: true,
      ease: 'Quad.out',
    });
  }
}

/** Canonical scene keys — the ONLY place scene name strings are defined. */
