import Phaser from 'phaser';
import { SceneKey } from './keys';
import { ASSET_MANIFEST } from '../config/assetManifest';
import { AudioManager } from '../systems/AudioManager';
import { t } from '../i18n/strings';
import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';

/**
 * PreloadScene — loads EVERY asset from the shared manifest (as SVGs at their
 * logical sizes) behind a loading bar, wires the iOS audio-unlock stub, then
 * advances to the menu. Nothing critical is lazy-loaded (spec §10.5).
 */
export class PreloadScene extends Phaser.Scene {
  constructor() {
    super({ key: SceneKey.Preload });
  }

  preload(): void {
    this.buildLoadingBar();

    // Register the first-gesture audio-unlock before anything could play audio.
    AudioManager.unlockOnFirstPointer(this);

    // The manifest is the single source of truth: iterate & load each SVG.
    for (const a of ASSET_MANIFEST) {
      this.load.svg(a.key, a.path, { width: a.width, height: a.height });
    }
  }

  create(): void {
    this.scene.start(SceneKey.Menu);
  }

  private buildLoadingBar(): void {
    const cx = GAME_WIDTH / 2;
    const cy = GAME_HEIGHT / 2;
    const barW = 520;
    const barH = 26;

    this.add
      .text(cx, cy - 48, t('loading'), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '22px',
        color: '#f4f7fa',
      })
      .setOrigin(0.5);

    const frame = this.add.graphics();
    frame.lineStyle(2, 0x5b6670, 1);
    frame.strokeRect(cx - barW / 2, cy - barH / 2, barW, barH);

    const fill = this.add.graphics();
    const pct = this.add
      .text(cx, cy + 40, '0%', {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '16px',
        color: '#9fb0bd',
      })
      .setOrigin(0.5);

    this.load.on(Phaser.Loader.Events.PROGRESS, (value: number) => {
      fill.clear();
      fill.fillStyle(0x6cc04a, 1);
      fill.fillRect(cx - barW / 2 + 3, cy - barH / 2 + 3, (barW - 6) * value, barH - 6);
      pct.setText(`${Math.round(value * 100)}%`);
    });
  }
}

import Phaser from 'phaser';
import { SceneKey } from './keys';
import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
import { KEYS } from '../config/assetManifest';
import { t } from '../i18n/strings';
import { createButton } from '../ui/Button';
import { AudioManager } from '../systems/AudioManager';

/**
 * MenuScene — title, Play (→ Game), and a persisted mute toggle. Fires no
 * analytics (start_game fires when the run actually begins, in GameScene).
 */
export class MenuScene extends Phaser.Scene {
  constructor() {
    super({ key: SceneKey.Menu });
  }

  create(): void {
    const cx = GAME_WIDTH / 2;

    this.add.image(cx, GAME_HEIGHT / 2, KEYS.screen_bg_menu);
    this.add.image(cx, 180, KEYS.ui_title_logo);

    this.add
      .text(cx, 180, t('menu_title'), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '54px',
        fontStyle: 'bold',
        color: '#20272e',
      })
      .setOrigin(0.5);

    this.add
      .text(cx, 330, t('menu_subtitle'), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '24px',
        color: '#3a444d',
      })
      .setOrigin(0.5);

    createButton(this, {
      x: cx,
      y: 450,
      texture: KEYS.ui_btn_play,
      label: t('menu_play'),
      onClick: () => this.scene.start(SceneKey.Game),
    });

    this.add
      .text(cx, 550, t('menu_hint'), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '20px',
        color: '#3a444d',
      })
      .setOrigin(0.5);

    this.buildMuteToggle();
  }

  private buildMuteToggle(): void {
    const muteBtn = this.add
      .image(GAME_WIDTH - 52, 52, this.muteTexture())
      .setInteractive({ useHandCursor: true });

    const label = this.add
      .text(GAME_WIDTH - 52, 90, this.muteLabel(), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '14px',
        color: '#9fb0bd',
      })
      .setOrigin(0.5, 0);

    muteBtn.on(Phaser.Input.Events.POINTER_UP, () => {
      AudioManager.toggle(this.sound);
      muteBtn.setTexture(this.muteTexture());
      label.setText(this.muteLabel());
    });
  }

  private muteTexture(): string {
    return AudioManager.isMuted() ? KEYS.ui_btn_mute_off : KEYS.ui_btn_mute_on;
  }

  private muteLabel(): string {
    return AudioManager.isMuted() ? t('menu_sound_off') : t('menu_sound_on');
  }
}

