  SCORE_SURVIVAL_PER_S,
  TARGET_DURATION_S,
} from '../config/gameConfig';
import { KEYS } from '../config/assetManifest';
import { t } from '../i18n/strings';
import { track, type FinishGameParams } from '../analytics/track';
import { createButton } from '../ui/Button';
import { HeroDog } from '../entities/HeroDog';

/**
 * GameScene — Phase 1 PLACEHOLDER run screen. It renders the park backdrop, the
 * hero, and a HUD, fires `start_game` on entry, and exposes TEMPORARY debug
 * controls (on-screen Win/Lose buttons + W/L keys) that end the run, fire
 * `finish_game`, and hand a result to ResultsScene. No real gameplay/physics yet
 * — this exists purely to make the flow navigable end-to-end.
 */
export class GameScene extends Phaser.Scene {
  private hero!: HeroDog;
  private scoreText!: Phaser.GameObjects.Text;
  private progressFill!: Phaser.GameObjects.Rectangle;

  private elapsedMs = 0;
  private score = 0;
  private finished = false;

  constructor() {
    super({ key: SceneKey.Game });
  }

  create(): void {
    this.elapsedMs = 0;
    this.score = 0;
    this.finished = false;

    this.buildBackground();
    this.hero = new HeroDog(this, HERO_X, GROUND_TOP_Y);
    this.buildHud();
    this.buildDebugFinishControls();

    // A round has begun.
    track('start_game');

    // Placeholder input: cosmetic hop only (real jump physics is Phase 2).
    this.input.on(Phaser.Input.Events.POINTER_DOWN, () => this.hero.nudgeJump());
    const space = this.input.keyboard?.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);
    space?.on('down', () => this.hero.nudgeJump());

    // Per-frame accumulator for active-play time (spec §7.2). Wired via the
    // scene UPDATE event so a later phase can freeze it during pause cleanly.
    this.events.on(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      this.events.off(Phaser.Scenes.Events.UPDATE, this.onUpdate, this);
    });
  }

  private buildBackground(): void {
    const cx = GAME_WIDTH / 2;
    this.add.image(cx, GAME_HEIGHT / 2, KEYS.park_bg_far);
    this.add.image(cx, GROUND_TOP_Y, KEYS.park_bg_near).setOrigin(0.5, 1);
    this.add
      .tileSprite(cx, GROUND_TOP_Y, GAME_WIDTH, GAME_HEIGHT - GROUND_TOP_Y, KEYS.ground_tile)
      .setOrigin(0.5, 0);
    this.add.image(cx, GAME_HEIGHT, KEYS.park_fg_grass).setOrigin(0.5, 1);
  }

  private buildHud(): void {
    // Score (top-left).
    this.scoreText = this.add.text(24, 18, `${t('hud_score')}: 0`, {
      fontFamily: 'system-ui, sans-serif',
      fontSize: '26px',
      fontStyle: 'bold',
      color: '#20272e',
    });

    // Hearts (top-left, under the score) — Phase 1 shows all full.
    for (let i = 0; i < MAX_HP; i++) {
      this.add.image(42 + i * 44, 74, KEYS.ui_heart_full);
    }

    // Full-width thin progress bar across the very top.
    this.add.rectangle(GAME_WIDTH / 2, 8, GAME_WIDTH - 40, 10, 0x2b3a46);
    this.progressFill = this.add
      .rectangle(20, 8, GAME_WIDTH - 40, 10, 0x6cc04a)
      .setOrigin(0, 0.5);
    this.progressFill.scaleX = 0;
  }

  private buildDebugFinishControls(): void {
    this.add
      .text(GAME_WIDTH / 2, GAME_HEIGHT - 98, t('game_debug_hint'), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '16px',
        color: '#20272e',
      })
      .setOrigin(0.5);

    createButton(this, {
      x: GAME_WIDTH / 2 - 135,
      y: GAME_HEIGHT - 50,
      width: 240,
      height: 56,
      label: t('game_debug_win'),
      onClick: () => this.finishRun('win'),
    });
    createButton(this, {
      x: GAME_WIDTH / 2 + 135,
      y: GAME_HEIGHT - 50,
      width: 240,
      height: 56,
      label: t('game_debug_lose'),
      onClick: () => this.finishRun('lose'),
    });

    const kb = this.input.keyboard;
    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.W).on('down', () => this.finishRun('win'));
    kb?.addKey(Phaser.Input.Keyboard.KeyCodes.L).on('down', () => this.finishRun('lose'));
  }

  private onUpdate(_time: number, delta: number): void {
    if (this.finished) return;

    this.elapsedMs += delta;
    const seconds = this.elapsedMs / 1000;

    this.score = Math.floor(seconds * SCORE_SURVIVAL_PER_S);
    this.scoreText.setText(`${t('hud_score')}: ${this.score}`);

    const progress = Phaser.Math.Clamp(seconds / TARGET_DURATION_S.nominal, 0, 1);
    this.progressFill.scaleX = progress;
  }

  private finishRun(result: 'win' | 'lose'): void {
    if (this.finished) return;
    this.finished = true;

    const payload: FinishGameParams = {
      result,
      score: this.score,
      duration_s: Math.round(this.elapsedMs / 1000),
    };
    track('finish_game', payload);
    this.scene.start(SceneKey.Results, payload);
  }
}

import Phaser from 'phaser';
import { SceneKey } from './keys';
import { GAME_WIDTH, GAME_HEIGHT } from '../config/gameConfig';
import { KEYS } from '../config/assetManifest';
import { t } from '../i18n/strings';
import { track, type FinishGameParams } from '../analytics/track';
import { createButton } from '../ui/Button';
import { ENV, buildBuyUrl, buyDestination } from '../config/env';

/**
 * ResultsScene — Victory or Game Over depending on the `result` param, the final
 * score, the promo-code chip, the buy CTA (fires `click_buy` then opens the
 * UTM-tagged buy URL in a new tab), and Play-again (→ a fresh run).
 */
export class ResultsScene extends Phaser.Scene {
  constructor() {
    super({ key: SceneKey.Results });
  }

  create(data: FinishGameParams): void {
    const win = data.result === 'win';
    const cx = GAME_WIDTH / 2;

    this.add.image(cx, GAME_HEIGHT / 2, win ? KEYS.screen_bg_victory : KEYS.screen_bg_gameover);
    this.add.image(cx, 250, win ? KEYS.dog_victory : KEYS.dog_defeat);

    this.add
      .text(cx, 90, win ? t('results_victory_title') : t('results_gameover_title'), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '48px',
        fontStyle: 'bold',
        color: '#20272e',
      })
      .setOrigin(0.5);

    this.add
      .text(cx, 380, t('results_score', { score: data.score }), {
        fontFamily: 'system-ui, sans-serif',
        fontSize: '30px',
        color: '#20272e',
      })
      .setOrigin(0.5);

    // Promo chip + code.
    this.add.image(cx, 460, KEYS.ui_promo_chip);
    this.add
      .text(cx, 460, `${t('results_promo_label')} ${ENV.promoCode}`, {
        fontFamily: 'monospace',
        fontSize: '26px',
        fontStyle: 'bold',
        color: '#20272e',
      })
      .setOrigin(0.5);

    // The conversion CTA.
    createButton(this, {
      x: cx,
      y: 565,
      texture: KEYS.ui_btn_cta,
      label: t('results_cta'),
      onClick: () => this.onBuy(),
    });

    // Secondary: play again → fresh run (a new start_game fires in GameScene).
    createButton(this, {
      x: cx,
      y: 660,
      texture: KEYS.ui_btn_play_again,
      label: t('results_play_again'),
      onClick: () => this.scene.start(SceneKey.Game),
    });
  }

  private onBuy(): void {
    track('click_buy', { destination: buyDestination(), promo_code: ENV.promoCode });
    window.open(buildBuyUrl(), '_blank', 'noopener');
  }
}

import Phaser from 'phaser';
import { GAME_WIDTH, GAME_HEIGHT, BACKGROUND_COLOR } from './config/gameConfig';
import { BootScene } from './scenes/BootScene';
import { PreloadScene } from './scenes/PreloadScene';
import { MenuScene } from './scenes/MenuScene';
import { GameScene } from './scenes/GameScene';
import { ResultsScene } from './scenes/ResultsScene';
import { initAnalytics } from './analytics/track';
import { installOrientationGuard } from './ui/OrientationOverlay';

// One-time page bootstrap: env-gated analytics loader (safe no-op without
// VITE_* ids) and the DOM orientation guard, both independent of Phaser.
initAnalytics();
installOrientationGuard();

const config: Phaser.Types.Core.GameConfig = {
  type: Phaser.AUTO,
  parent: 'game',
  width: GAME_WIDTH, // fixed logical resolution 1280×720 (landscape 16:9)
  height: GAME_HEIGHT,
  backgroundColor: BACKGROUND_COLOR,
  scale: {
    mode: Phaser.Scale.FIT, // scale the logical canvas to fit any viewport…
    autoCenter: Phaser.Scale.CENTER_BOTH, // …and center it (letterbox on portrait)
  },
  physics: {
    default: 'arcade',
    arcade: {
      gravity: { x: 0, y: 0 }, // per-body gravity is set by entities in Phase 2
      debug: false,
    },
  },
  render: { antialias: true },
  // Scene order = boot flow: Boot → Preload → Menu → Game → Results.
  scene: [BootScene, PreloadScene, MenuScene, GameScene, ResultsScene],
};

new Phaser.Game(config);

// gen-placeholders.mjs — emit a greybox placeholder SVG for EVERY asset key.
//
// Run: `npm run gen:placeholders` (or `node scripts/gen-placeholders.mjs`).
//
// Each file is a single colored <rect> at the key's logical dimensions with the
// key name + dimensions as visible text, so the app runs end-to-end in Phase 1.
// Phase 2 REPLACES these files against the EXACT same keys/paths/dimensions.
//
// This list MUST stay in lock-step with src/config/assetManifest.ts (same keys,
// same width/height, same folder → same `assets/<folder>/<key>.svg` path).

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const OUT_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'assets');

/** Fill colour per namespace folder (purely to make greyboxes scannable). */
const COLORS = {
  dog: '#cfd8e3',
  env: '#d6e8cf',
  entities: '#f2d7a8',
  vfx: '#e6d3f2',
  ui: '#dfe3e8',
  screens: '#eef1f4',
};

// [folder, key, width, height]
const ASSETS = [
  ['dog', 'dog_run', 140, 150],
  ['dog', 'dog_jump', 140, 150],
  ['dog', 'dog_hit', 140, 150],
  ['dog', 'dog_victory', 160, 170],
  ['dog', 'dog_defeat', 160, 170],
  ['dog', 'dog_armored', 150, 160],

  ['env', 'park_bg_far', 1280, 720],
  ['env', 'park_bg_near', 1280, 360],
  ['env', 'ground_tile', 256, 160],
  ['env', 'park_fg_grass', 1280, 140],

  ['entities', 'tick', 64, 64],
  ['entities', 'tablet', 56, 56],
  ['entities', 'bush', 150, 110],
  ['entities', 'puddle', 180, 50],
  ['entities', 'armor_pickup', 64, 64],
  ['entities', 'finish_line', 96, 480],

  ['vfx', 'vfx_armor_burst', 140, 140],
  ['vfx', 'vfx_armor_aura', 170, 170],

  ['ui', 'ui_heart_full', 52, 52],
  ['ui', 'ui_heart_empty', 52, 52],
  ['ui', 'ui_score_icon', 44, 44],
  ['ui', 'ui_btn_pause', 64, 64],
  ['ui', 'ui_btn_mute_on', 64, 64],
  ['ui', 'ui_btn_mute_off', 64, 64],
  ['ui', 'ui_progress_bar', 1180, 14],
  ['ui', 'ui_title_logo', 720, 260],
  ['ui', 'ui_btn_play', 360, 104],
  ['ui', 'ui_promo_chip', 460, 120],
  ['ui', 'ui_btn_cta', 380, 100],
  ['ui', 'ui_btn_play_again', 300, 84],
  ['ui', 'ui_pause_panel', 520, 360],

  ['screens', 'screen_bg_menu', 1280, 720],
  ['screens', 'screen_bg_victory', 1280, 720],
  ['screens', 'screen_bg_gameover', 1280, 720],
];

/** Font size that fits `text` inside `w` (approx 0.6em advance for monospace). */
function fitFont(text, w, h, cap) {
  const byHeight = Math.floor(Math.min(w, h) / 5);
  const byWidth = Math.floor((w - 8) / (text.length * 0.62));
  return Math.max(8, Math.min(byHeight, byWidth, cap));
}

function svg(key, w, h, color) {
  const dims = `${w}x${h}`;
  const keyFs = fitFont(key, w, h, 26);
  const dimFs = fitFont(dims, w, h, Math.max(8, Math.round(keyFs * 0.72)));
  const cx = w / 2;
  const cy = h / 2;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">
  <rect x="1" y="1" width="${w - 2}" height="${h - 2}" rx="6" fill="${color}" stroke="#5b6670" stroke-width="2"/>
  <text x="${cx}" y="${cy - keyFs * 0.15}" font-family="monospace" font-size="${keyFs}" fill="#20272e" text-anchor="middle" dominant-baseline="middle">${key}</text>
  <text x="${cx}" y="${cy + keyFs}" font-family="monospace" font-size="${dimFs}" fill="#48525c" text-anchor="middle" dominant-baseline="middle">${dims}</text>
</svg>
`;
}

let count = 0;
for (const [folder, key, w, h] of ASSETS) {
  const dir = join(OUT_ROOT, folder);
  mkdirSync(dir, { recursive: true });
  writeFileSync(join(dir, `${key}.svg`), svg(key, w, h, COLORS[folder]));
  count += 1;
}

console.log(`Generated ${count} placeholder SVGs under public/assets/`);

